// מחזור מעקב חדש (26.10.26): התבנית מכסה 12 שבועות. כשהקובץ נגמר והמתאמן/ת עדיין פעיל/ה — עותק מלא לתיקיית "ארכיון", ניקוי שקילות וצעדים,
// ותאריך ההתחלה ממשיך מהיום שאחרי (אותו יום בשבוע). הרמות וההיקפים נשארים באותו קובץ, כך שההתקדמות באפליקציה נמשכת. קובץ בלי תאריך התחלה מקבל את התאריך מהלוח
function rollTracking_(name, c, ws) {
  const today = startOfDay(new Date()), fd = d => Utilities.formatDate(d, 'Asia/Jerusalem', 'dd/MM/yyyy');
  const fA = ws.getRange('A7:A136').getFormulas(); if (!fA.some(f => /START_DATE/.test(f[0]))) return ''; // רק התבנית הרגילה (לא קבצים מותאמים)
  const dates = ws.getRange('A7:B136').getValues().map(wRow_).map(x => x[0] instanceof Date ? startOfDay(x[0]) : null).filter(Boolean);
  if (!dates.length) { const st = c.get('תחילת תהליך'), b3 = ws.getRange('B3'); if (b3.getValue() === '' && st instanceof Date && startOfDay(st) <= today) { b3.setValue(fd(startOfDay(st))); SpreadsheetApp.flush(); return 'start'; } return ''; }
  const last = dates.reduce((a, b) => b > a ? b : a); if (today <= last) return '';
  let ns = new Date(last.getTime() + 864e5); const gap = Math.floor((today - ns) / 864e5); if (gap >= 84) ns = new Date(ns.getTime() + Math.floor(gap / 84) * 84 * 864e5);
  const file = DriveApp.getFileById(c.fileId), from = ws.getRange('B3').getDisplayValue(), par = file.getParents(), dir = par.hasNext() ? par.next() : DriveApp.getRootFolder(), it = dir.getFoldersByName('ארכיון'), arc = it.hasNext() ? it.next() : dir.createFolder('ארכיון');
  const arcId = file.makeCopy(file.getName() + ' (' + from + ' עד ' + fd(last) + ')', arc).getId();
  const clr = []; fA.forEach((f, k) => { if (/START_DATE/.test(f[0])) clr.push('C' + (7 + k) + ':D' + (7 + k)); }); if (clr.length) ws.getRangeList(clr).clearContent();
  ws.getRange('B3').setValue(fd(ns)); ws.showRows(5, 132);
  const end = c.get('סוף תהליך'); if (end instanceof Date && end > ns) { const wk = Math.max(1, Math.ceil((end - ns) / 864e5 / 7)); if (wk < 12) { const fr = 5 + wk * 11; ws.hideRows(fr, 136 - fr + 1); } }
  SpreadsheetApp.flush();
  try { setOnbState(name, { cycles: (onbState(name).cycles || []).concat([{ from, to: fd(last), arc: arcId, at: new Date().toISOString() }]).slice(-10) }); } catch (e) {}
  try { CacheService.getScriptCache().removeAll(['pulse', 'onb']); } catch (e) {}
  return 'roll';
}
// כל בוקר: מגלגל קבצים שנגמרו לכל הפעילים (גם מי שממלא ישירות בקובץ ולא באפליקציה)
function trackingRollAll_() { const sh = SpreadsheetApp.getActive().getSheetByName(SHEET), vals = sh.getRange(FIRST, 1, ROWS, COLS.length).getValues(), done = [];
  vals.forEach(r => { const name = String(r[0]).trim(); if (!name || r[C['סטטוס'] - 1] !== 'פעיל') return; try { const c = clientRow(name); if (!c.fileId) return; const ws = SpreadsheetApp.openById(c.fileId).getSheetByName('שקילות יומיות'); if (!ws) return; const x = rollTracking_(name, c, ws); if (x) done.push(name + ':' + x); } catch (e) {} });
  return done; }
